// ── Merge Sort — O(n log n) time, O(n) space ──────────────────
// Divide: split in half. Conquer: sort each half. Combine: merge.

function mergeSort(arr) {
  if (arr.length <= 1) return arr; // base case
  const mid   = Math.floor(arr.length / 2);
  const left  = mergeSort(arr.slice(0, mid));  // conquer left
  const right = mergeSort(arr.slice(mid));      // conquer right
  return merge(left, right);                    // combine
}

function merge(left, right) {
  const result = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) result.push(left[i++]);
    else                      result.push(right[j++]);
  }
  return result.concat(left.slice(i)).concat(right.slice(j));
}

console.log(mergeSort([5, 2, 8, 1, 9, 3])); // [1, 2, 3, 5, 8, 9]

// ── Quickselect — expected O(n) k-th smallest ─────────────────
// Divide: partition around pivot. Conquer: ONE side only.
// Does NOT fully sort — stops when pivot lands at index k.

function quickselect(arr, k) {
  if (arr.length === 1) return arr[0];
  const pivot     = arr[Math.floor(Math.random() * arr.length)];
  const less      = arr.filter(x => x < pivot);
  const equal     = arr.filter(x => x === pivot);
  const greater   = arr.filter(x => x > pivot);

  if (k < less.length)               return quickselect(less, k);
  if (k < less.length + equal.length) return pivot;
  return quickselect(greater, k - less.length - equal.length);
}

const data = [7, 2, 10, 4, 3, 8, 1, 9, 5, 6];
console.log(quickselect(data, 0)); // 1  (0-indexed minimum)
console.log(quickselect(data, 4)); // 5  (median)
console.log(quickselect(data, 9)); // 10 (maximum)

// ── Master Theorem — T(n) = a·T(n/b) + O(n^d) ─────────────────
//
// Compare log_b(a) with d:
//   log_b(a) > d  →  T(n) = O(n^(log_b a))   [bottom-heavy]
//   log_b(a) = d  →  T(n) = O(n^d · log n)   [balanced]
//   log_b(a) < d  →  T(n) = O(n^d)            [top-heavy]
//
// Algorithm          a  b  d  log_b(a)  Result
// ─────────────────────────────────────────────
// Merge sort         2  2  1     1      O(n log n)  [balanced]
// Binary search      1  2  0     0      O(log n)    [balanced]
// Quickselect (avg)  1  2  1     0      O(n)        [top-heavy]
// Naive matrix mul   8  2  2     3      O(n^3)      [bottom-heavy]
// Strassen           7  2  2   2.807    O(n^2.807)  [bottom-heavy]

// ── Count inversions — D&C on merge sort ───────────────────────
// An inversion is a pair (i,j) where i<j but arr[i]>arr[j].
// Counting inversions = measuring how 'unsorted' an array is.
// Merge sort counts inversions during the merge step.

function mergeSortCount(arr) {
  if (arr.length <= 1) return { sorted: arr, inversions: 0 };
  const mid = Math.floor(arr.length / 2);
  const { sorted: left,  inversions: leftInv  } = mergeSortCount(arr.slice(0, mid));
  const { sorted: right, inversions: rightInv } = mergeSortCount(arr.slice(mid));
  const { sorted, inversions: splitInv } = mergeCount(left, right);
  return { sorted, inversions: leftInv + rightInv + splitInv };
}

function mergeCount(left, right) {
  const result = [];
  let i = 0, j = 0, inversions = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i++]);
    } else {
      // left[i..end] are all > right[j] — each is an inversion
      inversions += left.length - i;
      result.push(right[j++]);
    }
  }
  return { sorted: result.concat(left.slice(i)).concat(right.slice(j)), inversions };
}

console.log(mergeSortCount([2, 4, 1, 3, 5]).inversions); // 3  (pairs: (2,1),(4,1),(4,3))
